mapper.select:
        SELECT BOOKSET_ID code,BOOKSET_NAME name,BOOKSET_NAME shortName,BOOKSET_ID hidCode FROM BOK_BOOKSET
        where 1=1

        		AND	BOOKSET_TYPE = #{booksetType}


        	AND	(BOOKSET_ID like concat('%',concat(#{param},'%'))
        		OR BOOKSET_NAME like concat('%',concat(#{param},'%')))


	        	AND (BOOKSET_ID in 


	                	null) or BOOKSET_ID in (

                	#{item}

            	)

        order by bookset_type,BOOKSET_ID

SELECT BOOKSET_ID id,BOOKSET_NAME text FROM BOK_BOOKSET where 1=1
AND BOOKSET_TYPE != #{noBooksetType}
AND BOOKSET_TYPE = #{booksetType}
AND (BOOKSET_ID like concat('%',concat(#{search},'%')) OR BOOKSET_NAME like concat('%',concat(#{search},'%')))
order by bookset_type,BOOKSET_ID

SELECT A.BOOKSET_ID AS booksetId, A.BOOKSET_NAME AS booksetName, A.BOOKSET_TYPE AS booksetType, A.BOOKSET_TYPE AS booksetTypeCode, A.ACCT_SUBJECT_ID AS acctSubjectId, A.STANDARD_CCY AS standardCcy, A.STANDARD_CCY AS standardCcyCode, A.ACCT_SUBJECT_TYPE AS acctSubjectType, A.BOOKSET_ID_TMPL AS booksetIdTmpl, B.ACCT_STANDARD_NAME AS acctStandard, A.START_DATE AS startDate, A.END_DATE AS endDate FROM BOK_BOOKSET A LEFT JOIN bok_ACCT_STANDARD B ON B.ACCT_STANDARD_ID=A.ACCT_STANDARD WHERE BOOKSET_TYPE=#{booksetType}
AND BOOKSET_Id in
#{item}

select p.product_id as code from sys_batch_prd_grp g left join sys_batch_grp_prdlink p on g.seq_no = p.group_seq where system_code = 'SYS'
and g.seq_no in
#{item}
